+    }
+
+    @Test
+    void weekendPackageRefunds50Percent() {
+        // Friday March 12, 2027 to Sunday March 14, 2027
+        Reservation weekend = service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));
+        service.confirm(weekend.id());
+
+        assertEquals(new BigDecimal("820.00"), weekend.amountPaid());
+        assertEquals(new BigDecimal("410.00"), service.cancel(weekend.id()).refund());
+        assertEquals(new BigDecimal("410.00"), weekend.amountKept());
+    }
+
+    @Test
+    void weekendPackageRequiresFridayToSunday() {
+        assertEquals(
+                ErrorCode.INVALID_REQUEST,
+                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 2, RatePlan.WEEKEND_PACKAGE))));
+    }
